// Regenerated on every `npm run build`. Bundles the raw migration SQL as a JS
// module (src/lib/migrationsBundle.ts) so it's a real import — reliably
// included in serverless deployments (e.g. Vercel) whose build only traces
// actual `import`/`require` statements, not arbitrary files sitting in
// prisma/migrations/. Used by the Vercel-demo lazy database init; not needed
// for Docker or a plain Node server, which run `prisma migrate deploy`
// directly instead.
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const projectRoot = path.join(__dirname, "..");
const migrationsDir = path.join(projectRoot, "prisma", "migrations");

const dirs = fs
  .readdirSync(migrationsDir)
  .filter((d) => fs.statSync(path.join(migrationsDir, d)).isDirectory())
  .sort();

const migrations = dirs.map((dir) => ({
  name: dir,
  sql: fs.readFileSync(path.join(migrationsDir, dir, "migration.sql"), "utf-8"),
}));

const out = `// AUTO-GENERATED by scripts/generate-migrations-bundle.mjs on every build — do not edit by hand.
export type BundledMigration = { name: string; sql: string };
export const MIGRATIONS: BundledMigration[] = ${JSON.stringify(migrations, null, 2)};
`;

const outPath = path.join(projectRoot, "src", "lib", "migrationsBundle.ts");
fs.writeFileSync(outPath, out);
console.log(`Generated migrationsBundle.ts with ${migrations.length} migration(s).`);
